using System.Xml.Linq;
/// <summary>
/// Converting xml string to a color formatted html representation.
/// </summary>
class TFMFormXMLFormatter
{
}

Method.Source:
public static str htmlColorXML(XML _xml)
{
    Xml xml;
    if(_xml)
    {
        xml = strReplace(_xml, '&lt;' , '<');
        xml = strReplace(xml, '&gt;' , '>');
    } 
    else
    {
        xml = '<?xml version="1.0" encoding="UTF-8" standalone="no" ?><value>Nothing</value>';
    }
    return strFmt('%1',xml);
}
